CREATE FUNCTION pg_temp.checkout(p_user uuid, p_key uuid DEFAULT gen_random_uuid(), p_status public.evo_store_checkout_status DEFAULT 'active')
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE result uuid;
BEGIN
 INSERT INTO public.evo_store_checkouts(user_id,idempotency_key,request_fingerprint,status,currency,subtotal,
 shipping_full_name,shipping_phone,shipping_address_line1,shipping_city,shipping_state,shipping_postal_code,shipping_country,
 expires_at,released_at,expired_at,consumed_at)
 VALUES(p_user,p_key,'synthetic-fingerprint',p_status,'USD',10,'Synthetic Customer','0000000000','Synthetic street','Synthetic city','Synthetic state','000000','India',now()+interval '45 minutes',
 CASE WHEN p_status='released' THEN now() END,CASE WHEN p_status='expired' THEN now() END,CASE WHEN p_status='consumed' THEN now() END) RETURNING id INTO result;
 RETURN result;
END $$;
