SELECT ('18000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','checkout-'||n||'@example.test','',now(),'{}','{}',now(),now() FROM generate_series(1,3) n;
INSERT INTO public.profiles(id,username) SELECT ('18000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'checkout_'||n FROM generate_series(1,3) n;
INSERT INTO public.roles(id,code,name) VALUES('28000000-0000-4000-8000-000000000001','admin','Administrator') ON CONFLICT(code) DO NOTHING;
INSERT INTO public.user_roles(user_id,role_id) SELECT '18000000-0000-4000-8000-000000000003',id FROM public.roles WHERE code='admin';
