INSERT INTO public.addresses(id,user_id,full_name,phone,address_line1,city,state,postal_code) VALUES('98000000-0000-4000-8000-000000000002','18000000-0000-4000-8000-000000000002','Other Customer','000','Other street','Other city','Other state','000');
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT * FROM public.evo_store_checkouts$$,'42501',NULL,'anonymous cannot read evo_store_checkouts');
SELECT throws_ok($$SELECT * FROM public.evo_store_checkout_items$$,'42501',NULL,'anonymous cannot read evo_store_checkout_items');
SELECT throws_ok($$INSERT INTO public.evo_store_checkouts(id) VALUES(gen_random_uuid())$$,'42501',NULL,'anonymous cannot insert evo_store_checkouts');
SELECT throws_ok($$UPDATE public.evo_store_checkouts SET id=id$$,'42501',NULL,'anonymous cannot update evo_store_checkouts');
SELECT throws_ok($$DELETE FROM public.evo_store_checkouts$$,'42501',NULL,'anonymous cannot delete evo_store_checkouts');
SELECT throws_ok($$INSERT INTO public.evo_store_checkout_items(id) VALUES(gen_random_uuid())$$,'42501',NULL,'anonymous cannot insert evo_store_checkout_items');
SELECT throws_ok($$UPDATE public.evo_store_checkout_items SET id=id$$,'42501',NULL,'anonymous cannot update evo_store_checkout_items');
SELECT throws_ok($$DELETE FROM public.evo_store_checkout_items$$,'42501',NULL,'anonymous cannot delete evo_store_checkout_items');
RESET ROLE; SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','18000000-0000-4000-8000-000000000001',true);
SELECT is((SELECT count(*)::integer FROM public.evo_store_checkouts WHERE user_id='18000000-0000-4000-8000-000000000002'),0,'other customer headers hidden');
SELECT is((SELECT count(*)::integer FROM public.evo_store_checkouts WHERE user_id='18000000-0000-4000-8000-000000000001'),5,'own active and terminal history visible');
SELECT is((SELECT count(*)::integer FROM public.evo_store_checkout_items),2,'only own items visible');
SELECT throws_ok($$INSERT INTO public.evo_store_checkouts(id) VALUES(gen_random_uuid())$$,'42501',NULL,'customer cannot insert evo_store_checkouts');
SELECT throws_ok($$UPDATE public.evo_store_checkouts SET id=id$$,'42501',NULL,'customer cannot update evo_store_checkouts');
SELECT throws_ok($$DELETE FROM public.evo_store_checkouts$$,'42501',NULL,'customer cannot delete evo_store_checkouts');
SELECT throws_ok($$INSERT INTO public.evo_store_checkout_items(id) VALUES(gen_random_uuid())$$,'42501',NULL,'customer cannot insert evo_store_checkout_items');
SELECT throws_ok($$UPDATE public.evo_store_checkout_items SET id=id$$,'42501',NULL,'customer cannot update evo_store_checkout_items');
SELECT throws_ok($$DELETE FROM public.evo_store_checkout_items$$,'42501',NULL,'customer cannot delete evo_store_checkout_items');
SELECT throws_ok($$UPDATE public.evo_store_checkouts SET address_id='98000000-0000-4000-8000-000000000002'$$,'42501',NULL,'customer cannot attach another users saved address through direct DML');
SELECT set_config('request.jwt.claim.sub','18000000-0000-4000-8000-000000000003',true);
SELECT is((SELECT count(*)::integer FROM public.evo_store_checkouts),6,'staff sees all checkout history');
SELECT is((SELECT count(*)::integer FROM public.evo_store_checkout_items),3,'staff sees all items');
SELECT throws_ok($$UPDATE public.evo_store_checkouts SET id=id$$,'42501',NULL,'staff has no direct snapshot updates evo_store_checkouts');
SELECT throws_ok($$UPDATE public.evo_store_checkout_items SET id=id$$,'42501',NULL,'staff has no direct snapshot updates evo_store_checkout_items');
SELECT throws_ok($$INSERT INTO public.evo_store_checkouts(id) VALUES(gen_random_uuid())$$,'42501',NULL,'staff cannot directly insert evo_store_checkouts');
SELECT throws_ok($$DELETE FROM public.evo_store_checkouts$$,'42501',NULL,'staff cannot directly delete evo_store_checkouts');
SELECT throws_ok($$INSERT INTO public.evo_store_checkout_items(id) VALUES(gen_random_uuid())$$,'42501',NULL,'staff cannot directly insert evo_store_checkout_items');
SELECT throws_ok($$DELETE FROM public.evo_store_checkout_items$$,'42501',NULL,'staff cannot directly delete evo_store_checkout_items');
RESET ROLE; SET LOCAL ROLE service_role;
SELECT is((SELECT count(*)::integer FROM public.evo_store_checkouts),6,'service role can read checkout history');
SELECT lives_ok($$INSERT INTO public.evo_store_checkouts(id,user_id,idempotency_key,request_fingerprint,status,currency,subtotal,shipping_full_name,shipping_phone,shipping_address_line1,shipping_city,shipping_state,shipping_postal_code,shipping_country,expires_at,released_at) VALUES('a8000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001',gen_random_uuid(),'service-fixture','released','USD',10,'Synthetic Service','000','Synthetic street','Synthetic city','Synthetic state','000','India',now()+interval '45 minutes',now())$$,'service role can insert complete checkout with currency CHECK');
SELECT lives_ok($$UPDATE public.evo_store_checkouts SET shipping_phone='001' WHERE id='a8000000-0000-4000-8000-000000000001'$$,'service role can repair snapshot without changing terminal state');
SELECT throws_ok($$UPDATE public.evo_store_checkouts SET status='active',released_at=NULL WHERE id='a8000000-0000-4000-8000-000000000001'$$,'23514',NULL,'service role cannot resurrect terminal reservation');
SELECT lives_ok($$INSERT INTO public.evo_store_checkout_items(id,checkout_id,variant_id,product_id,quantity,currency,unit_price,line_subtotal,product_name,sku) VALUES('b8000000-0000-4000-8000-000000000001','a8000000-0000-4000-8000-000000000001','58000000-0000-4000-8000-000000000003','48000000-0000-4000-8000-000000000001',1,'USD',10,10,'Synthetic Service','SERVICE-SYNTHETIC')$$,'service role can insert item with currency CHECK and FK');
SELECT lives_ok($$UPDATE public.evo_store_checkout_items SET unit_price=11,line_subtotal=11 WHERE id='b8000000-0000-4000-8000-000000000001'$$,'service role can update item consistently');
SELECT lives_ok($$DELETE FROM public.evo_store_checkout_items WHERE id='b8000000-0000-4000-8000-000000000001'$$,'service role can explicitly delete item');
SELECT lives_ok($$DELETE FROM public.evo_store_checkouts WHERE id='a8000000-0000-4000-8000-000000000001'$$,'service role can delete unreferenced checkout');
RESET ROLE;
SELECT ok(NOT EXISTS ((SELECT * FROM public.evo_store_inventory EXCEPT SELECT * FROM inventory_before) UNION ALL (SELECT * FROM inventory_before EXCEPT SELECT * FROM public.evo_store_inventory)),'evo_store_inventory unchanged by checkout fixture operations');
SELECT ok(NOT EXISTS ((SELECT * FROM public.evo_store_inventory_movements EXCEPT SELECT * FROM movements_before) UNION ALL (SELECT * FROM movements_before EXCEPT SELECT * FROM public.evo_store_inventory_movements)),'evo_store_inventory_movements unchanged by checkout fixture operations');
SELECT ok(NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid IN ('public.evo_store_checkouts'::regclass,'public.evo_store_checkout_items'::regclass) AND NOT t.tgisinternal AND p.proname NOT IN ('set_updated_at','guard_evo_store_checkout_terminal_status')),'no reservation/inventory mutation triggers');
SELECT ok(to_regclass('public.evo_store_inventory_reservations') IS NULL,'evo_store_inventory_reservations not introduced');
SELECT ok(to_regclass('public.evo_store_inventory_reservation_items') IS NULL,'evo_store_inventory_reservation_items not introduced');
SELECT ok(to_regclass('public.evo_store_orders') IS NULL,'evo_store_orders not introduced');
SELECT ok(to_regclass('public.evo_store_order_items') IS NULL,'evo_store_order_items not introduced');
SELECT ok(to_regclass('public.evo_store_payments') IS NULL,'evo_store_payments not introduced');
SELECT * FROM finish();
ROLLBACK;
